 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();readonly List<Gamepad> pads=new List<Gamepad>();readonly List<float> frames=new List<float>();BowlingMatch m;Keyboard keyboard;InputSettings original,probe;string flag,folder,saved;bool hadSave,failed,finished;float sampleStart;long memory;int gc;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){foreach(var key in new[]{"-tsBowlingQuick","-tsBowlingUpdate","-tsBowlingFourAI","-tsBowlingEightAI"})if(Array.IndexOf(Environment.GetCommandLineArgs(),key)>=0){var g=new GameObject("Bowling development validation");DontDestroyOnLoad(g);g.AddComponent<BowlingSmoke>().flag=key;return;}}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("BowlingSmoke");Directory.CreateDirectory(folder);hadSave=LWS.TruckSports.SportsPrefs.HasKey(BowlingMatch.SetupKey);saved=LWS.TruckSports.SportsPrefs.GetString(BowlingMatch.SetupKey);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;UnityEngine.Random.InitState(1337);keyboard=InputSystem.AddDevice<Keyboard>("Bowling injected keyboard");Application.logMessageReceived+=Log;records.Add("Physical pads before injection: "+Gamepad.all.Count);steps.Push(Run());}
 void Log(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error){failed=true;records.Add("RUNTIME ERROR "+message);}}
 void Update(){if(finished)return;if(m!=null&&m.InMatch&&!m.Paused&&!m.Finished&&m.menus.Screen==BowlingScreen.Play)frames.Add(Time.unscaledDeltaTime);try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator nested){steps.Push(nested);continue;}return;}Finish(failed?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError("BOWLING_SMOKE_FAIL "+e);Finish(2);}}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Wait(Func<bool> predicate,float seconds,string name){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+name+" phase="+(m==null?"none":m.lanes[0].Phase.ToString())+" position="+(m==null?Vector3.zero:m.lanes[0].truck.body.position)+" speed="+(m==null?0:m.lanes[0].truck.Speed));yield return null;}}
 void Check(bool condition,string name){if(!condition)throw new Exception(name+" lane="+(m==null?"none":m.lanes[0].Phase.ToString())+" position="+(m==null?Vector3.zero:m.lanes[0].truck.body.position));records.Add("PASS "+name);Debug.Log("BOWLING_SMOKE_PASS "+name);}
