  yield return Begin(1,BowlingMode.Simultaneous);var lane=m.lanes[0];var truck=lane.truck;Check(!lane.cab.view.orthographic&&lane.cab.view.nearClipPlane<.03f,"perspective cab camera / near clipping");Check(lane.pins[0].GetComponent<Renderer>().bounds.size.y>truck.GetComponent<Collider>().bounds.size.y*2,"pins full-size relative to tiny truck");Check(truck.wheels.Length==4,"NWH four-wheel physics adapter");yield return Capture("03-first-person-approach");float grip=truck.Grip;yield return Wait(()=>lane.Committed,8,"actual approach drive");Check(truck.Speed>3&&truck.body.position.z>=0,"actual NWH acceleration from approach crosses foul line legally");yield return Capture("04-first-person-lane");yield return Wait(()=>lane.Furthest>35||lane.Gutter,8,"lane progression");Check(truck.Grip<grip,"progressive reduction in NWH traction");yield return Wait(()=>lane.ScoreLocks>0,20,"physical delivery settles");Check(truck.PinImpacts>0&&lane.LegalPinContact,"actual truck to pin physical contacts");Check(lane.LastPins>0&&lane.Owner.score.Deliveries==1,"settled actual pinfall scored once");yield return Capture("05-delivery-result");int locks=lane.ScoreLocks;int rolls=lane.Owner.score.Deliveries;yield return Wait(()=>lane.Sweeps>0,5,"animated sweep");Check(lane.Owner.score.Deliveries==rolls&&lane.ScoreLocks==locks,"pinsetter does not score again");yield return Wait(()=>lane.Phase==BowlingPhase.Approach,5,"respawn");Check(truck.body.position.z<0,"cab returns with truck to approach");if(flag=="-tsBowlingQuick")yield break;
