 IEnumerator HumanHandling(){yield return Begin(1,BowlingMode.Simultaneous);var lane=m.lanes[0];var truck=lane.truck;m.setup.players[0].source=BowlingSource.Keyboard;Keys();yield return Delay(.2f);Keys(Key.W);yield return Delay(.8f);float speed=Vector3.Dot(truck.body.linearVelocity,truck.transform.forward);Check(speed>1,"actual keyboard forward acceleration");Keys(Key.S);yield return Delay(.15f);Check(Vector3.Dot(truck.body.linearVelocity,truck.transform.forward)<speed&&truck.wheels[0].BrakeTorque>0&&Mathf.Abs(truck.wheels[0].MotorTorque)<.01f,"opposite throttle brakes before reverse");yield return Wait(()=>Vector3.Dot(truck.body.linearVelocity,truck.transform.forward)<-.3f,3,"held reverse after stopping");Check(truck.throttle<0,"held reverse drives backward after stop");yield return Wait(()=>Vector3.Dot(truck.body.linearVelocity,truck.transform.forward)<-3,2,"established reverse speed");float backward=Vector3.Dot(truck.body.linearVelocity,truck.transform.forward);Keys(Key.W);yield return Delay(.08f);Check(truck.wheels[0].BrakeTorque>0&&Vector3.Dot(truck.body.linearVelocity,truck.transform.forward)>backward,"forward brakes backward motion");Keys();
