 IEnumerator InputCases(){m.ChangeSetup();m.setup.mode=BowlingMode.Simultaneous;m.setup.count=4;for(int i=0;i<4;i++){m.setup.players[i].source=BowlingSource.Keyboard;var d=BowlingSetup.Defaults()[i];m.setup.players[i].forward=d.forward;m.setup.players[i].left=d.left;m.setup.players[i].back=d.back;m.setup.players[i].right=d.right;}Check(m.StartMatch(),"four keyboard clusters ready");Keys();yield return Delay(.2f);Keys(Key.W,Key.UpArrow,Key.T,Key.I);yield return Delay(.3f);for(int i=0;i<4;i++)Check(m.lanes[i].truck.throttle>.9f,"keyboard drives independent lane "+i);yield return Capture("08-four-lane-keyboard");Keys();yield return Delay(.2f);m.ChangeSetup();
