d return Wait(()=>m.lanes[0].Phase==BowlingPhase.Lifting,6,"pinsetter disconnect phase");var machine=m.lanes[0];Vector3 plate=machine.plate.position;int rolls=machine.Owner.score.Deliveries;InputSystem.RemoveDevice(pads[0]);yield return Delay(.35f);Check(m.Paused&&machine.Phase==BowlingPhase.Lifting&&machine.plate.position==plate&&machine.Owner.score.Deliveries==rolls,"pinsetter disconnect freezes animation and locked score paused="+m.Paused+" phase="+machine.Phase+" plate="+machine.plate.position+" before="+plate+" rolls="+machine.Owner.score.Deliveries+" beforeRolls="+rolls);InputSystem.AddDevice(pads[0]);Pad(pads[0]);yield return Delay(.2f);Pad(pads[0],button:GamepadButton.South);yield return Delay(.2f);Check(!m.Paused,"pinsetter reconnect resumes through fresh owner confirmation");Pad(pads[0]);yield return Wait(()=>machine.Phase==BowlingPhase.Approach,4,"pinsetter completes after reconnect");Check(machine.Owner.score.Deliveries==rolls,"resumed pinsetter cannot double-score");m.ChangeSetup();
