 IEnumerator TieFixture(){records.Add("Tie/result presentation is a zero-score rule-outcome fixture; full autonomous flags never inject scores.");yield return Begin(2,BowlingMode.Simultaneous);m.Pause();for(int i=0;i<2;i++)for(int roll=0;roll<20;roll++)m.setup.players[i].score.Record(0);m.Next(m.lanes[0],true);m.Next(m.lanes[1],true);Check(m.Finished&&m.Winners.Length==2&&m.menus.resultText.text.Contains("TIE FOR FIRST"),"tied final standings retain both winners");yield return Capture("09-tie-fixture");Check(m.StartMatch()&&m.setup.players[0].score.Deliveries==0,"rematch after tie clears completed scores");yield return Delay(.2f);m.ChangeSetup();}
 IEnumerator Transitions(){for(int repeat=0;repeat<2;repeat++){SportsNavigation.FrontEnd();yield return Delay(.3f);Check(UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>().Page==1,"collection return selection "+repeat);foreach(var sport in new[]{SportsNavigation.Billiards,SportsNavigation.Hockey,SportsNavigation.Bowling}){SportsNavigation.LoadSport(sport);yield return Delay(.35f);Check(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1&&UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length==1,"single event/listener after "+sport+" "+repeat);SportsNavigation.FrontEnd();yield return Delay(.3f);}}yield return Enter();}
 IEnumerator Autonomous(bool hot){int count=hot?8:4;records.Add("AUTONOMOUS physical match: no injected pinfall, score assignments, truck relocation or shot-to-shot setup; only normal game respawns/racks. Hot seat uses timeScale=3 for elapsed-time validation; four-lane sample timeScale=1.");yield return Begin(count,hot?BowlingMode.HotSeat:BowlingMode.Simultaneous);if(hot)Time.timeScale=3;frames.Clear();sampleStart=Time.realtimeSinceStartup;memory=GC.GetTotalMemory(false);gc=GC.CollectionCount(0);bool independent=false,earlyFinish=false;float progressAt=sampleStart+20;int captures=0;int[] observedLocks=new int[4];for(int i=0;i<4;i++)observedLocks[i]=m.lanes[i].ScoreLocks;yield return Capture(hot?"10-eight-ai-cab":"10-four-ai-cabs");
  while(!m.Finished){for(int i=0;i<(hot?1:4);i++){var lane=m.lanes[i];if(lane.ScoreLocks!=observedLocks[i]){observedLocks[i]=lane.ScoreLocks;if(lane.LastPins>0&&!lane.LegalPinContact)throw new Exception("Unattributed pinfall after pinsetter: lane="+i+" pins="+lane.LastPins);}}if(Time.realtimeSinceStartup-sampleStart>(hot?1600:600))throw new Exception("Autonomous match stalled");if(!hot){int frame=m.setup.players[0].score.Frame;for(int i=1;i<count;i++)if(m.setup.players[i].score.Frame!=frame)independent=true;for(int i=0;i<count;i++)if(m.setup.players[i].score.Finished)earlyFinish=true;}if(Time.realtimeSinceStartup>progressAt){progressAt+=20;var b=new System.Text.StringBuilder("AUTONOMOUS_PROGRESS ");for(int i=0;i<count;i++)b.Append(i).Append(':').Append(m.setup.players[i].score.Frame+1).Append('/').Append(m.setup.players[i].score.Deliveries).Append(' ');Debug.Log(b.ToString());if(captures++<3)yield return Capture("11-progress-"+captures);}yield return null;}
  float elapsed=Time.realtimeSinceStartup-sampleStart;for(int i=0;i<count;i++)Check(m.setup.players[i].score.Finished&&m.setup.players[i].score.FinalTotal>=0&&m.setup.players[i].score.FinalTotal<=300,"complete ten-frame participant "+i+" score="+m.setup.players[i].score.FinalTotal+" deliveries="+m.setup.players[i].score.Deliveries);
  int impacts=0,pinfall=0,sweeps=0;foreach(var l in m.lanes){impacts+=l.truck.PinImpacts;sweeps+=l.Sweeps;}for(int i=0;i<count;i++)for(int f=0;f<10;f++)foreach(int p in m.setup.players[i].score.FrameRolls(f))pinfall+=p;Check(impacts>0&&pinfall>0,"autonomous physical contacts and pinfall");Check(m.menus.Screen==BowlingScreen.Result,"all-AI final results remain available");if(!hot)Check(independent,"simultaneous lanes advance independently");Check(hot||earlyFinish,"a finished lane does not stop unfinished lanes");yield return Capture("12-final-standings");m.menus.Action("scorecard");yield return Capture("13-full-scorecard");records.Add("AUTONOMOUS_COMPLETE mode="+m.setup.mode+" elapsedSeconds="+elapsed.ToString("F1")+" timeScale="+Time.timeScale+" impacts="+impacts+" pinfall="+pinfall+" sweeps="+sweeps);Performance();Time.timeScale=1;m.menus.Action("back");Check(m.StartMatch(),"rematch retains participants");for(int i=0;i<count;i++)Check(m.setup.players[i].score.Deliveries==0&&m.setup.players[i].name=="Bowler "+(i+1),"rematch resets score and retains identity "+i);yield return Delay(.3f);
 }
 void Performance(){if(frames.Count==0)return;frames.Sort();double sum=0;foreach(float f in frames)sum+=f;records.Add("SUSTAINED frames="+frames.Count+" meanMs="+(sum/frames.Count*1000).ToString("F2")+" p95Ms="+(frames[(int)(frames.Count*.95f)]*1000).ToString("F2")+" p99Ms="+(frames[(int)(frames.Count*.99f)]*1000).ToString("F2")+" worstMs="+(frames[frames.Count-1]*1000).ToString("F2")+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" gen0="+(GC.CollectionCount(0)-gc));records.Add("ENVIRONMENT GPU="+SystemInfo.graphicsDeviceName+" API="+SystemInfo.graphicsDeviceType+" resolution="+Screen.width+"x"+Screen.height+" vSync="+QualitySettings.vSyncCount);}
 void Finish(int code){if(finished)return;finished=true;Application.logMessageReceived-=Log;Time.timeScale=1;foreach(var p in pads)if(p.added)InputSystem.RemoveDevice(p);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;if(probe!=null)Destroy(probe);if(hadSave)LWS.TruckSports.SportsPrefs.SetString(BowlingMatch.SetupKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(BowlingMatch.SetupKey);LWS.TruckSports.SportsPrefs.Save();File.WriteAllLines(Path.Combine(folder,"results.txt"),records);Debug.Log("BOWLING_SMOKE_FINISHED code="+code);Application.Quit(code);}
